import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"コマンドライン検索 (lff)","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/cli.md","filePath":"ja-JP/user-guide/cli.md","lastUpdated":1785993908000}'),d={name:"ja-JP/user-guide/cli.md"};function l(o,a,p,r,n,h){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="コマンドライン検索-lff" tabindex="-1">コマンドライン検索 (lff) <a class="header-anchor" href="#コマンドライン検索-lff" aria-label="Permalink to &quot;コマンドライン検索 (lff)&quot;">​</a></h1><p>Lertaro には、小さなコマンドラインコンパニオンツール <strong><code>lff</code></strong> も同梱されています。これは fzf スタイルのあいまい検索ツールで、独自に検索用の仕組みを持つのではなく、App 自体がすでに維持しているインデックスをそのまま検索します。ターミナルで生活していて、検索ウィンドウだけでなくそこでも Lertaro の検索 (あいまい検索、ピンインエイリアス、ネットワークドライブなど全部) を使いたい人向けの機能です。</p><p><code>lff</code> は Lertaro App がすでに実行中であることを前提としています。自分で何かを再スキャンするのではなく、ローカルのユーザーごとのパイプ経由で App とやり取りします。App が実行されていない場合、<code>lff</code> はハングすることなく、stderr にエラーを出してすぐに失敗します。</p><h2 id="セットアップ" tabindex="-1">セットアップ <a class="header-anchor" href="#セットアップ" aria-label="Permalink to &quot;セットアップ&quot;">​</a></h2><p><code>lff.exe</code> は App と一緒にインストールされます。インストーラーのタスク選択ページで <strong>Add the lff command-line search tool to PATH</strong> にチェックを入れると、どのターミナルからでも <code>lff</code> として実行できるようになります。これにより Lertaro のインストールフォルダーがシステムの PATH に追加されます。インストール後に新しいターミナルウィンドウを開いてください。インストール時にすでに開いていたターミナルには変更が反映されません。</p><p>このオプションを選択しなかった場合でも、Lertaro のインストール先から直接実行することは可能です。</p><h2 id="基本的な使い方" tabindex="-1">基本的な使い方 <a class="header-anchor" href="#基本的な使い方" aria-label="Permalink to &quot;基本的な使い方&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff</span></span></code></pre></div><p>を実行すると、対話式のピッカーが開きます。入力すると、App 自身の検索と全く同じようにあいまい検索でフィルタリングされます。中国語ファイル名に対するピンインエイリアスのマッチングも含まれます (<a href="./search-syntax.html">検索構文</a> を参照)。</p><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td>入力</td><td>検索結果を絞り込む</td></tr><tr><td>↑ / ↓</td><td>ハイライトを移動</td></tr><tr><td>Page Up / Page Down</td><td>1 ページ分ジャンプ</td></tr><tr><td>← / →</td><td>クエリ内でテキストカーソルを移動</td></tr><tr><td>Tab</td><td>ハイライトされている検索結果の選択状態をトグル (選択済みの行には <code>*</code> が表示されます)</td></tr><tr><td>Enter</td><td>選択したパス (何も選択されていなければハイライト中の 1 件のみ) を出力して終了</td></tr><tr><td>Esc / Ctrl+C</td><td>何も出力せずに終了</td></tr></tbody></table><h2 id="クエリを事前入力する" tabindex="-1">クエリを事前入力する <a class="header-anchor" href="#クエリを事前入力する" aria-label="Permalink to &quot;クエリを事前入力する&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff report</span></span></code></pre></div><p>および</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo report | lff</span></span></code></pre></div><p>はどちらも、<code>report</code> であらかじめ絞り込まれた状態で開きます。いずれの方法でも、クエリボックスに事前入力してそれを入力した場合と同じ検索を開始するだけです。結果を自動的に選択したり自動的に出力したりすることは一切ないため、自分で移動して Enter または Tab を押す必要があります。</p><h2 id="複数の検索結果を選択する" tabindex="-1">複数の検索結果を選択する <a class="header-anchor" href="#複数の検索結果を選択する" aria-label="Permalink to &quot;複数の検索結果を選択する&quot;">​</a></h2><p>Tab キーはハイライト中の行の選択/解除を切り替えます。選択済みの行はクエリを変更しても保持されるため、あるファイルを検索して選択し、別のものを検索してそれも選択する、といったことができます。ステータスラインには現在選択されている件数が表示されます。何か選択されている状態で Enter を押すと、現在ハイライトされているものに関わらず、選択済みのすべてのパスが 1 行ずつ出力されます。</p><h2 id="検索結果を他のコマンドで使う" tabindex="-1">検索結果を他のコマンドで使う <a class="header-anchor" href="#検索結果を他のコマンドで使う" aria-label="Permalink to &quot;検索結果を他のコマンドで使う&quot;">​</a></h2><p><code>lff</code> の対話式ピッカーはコンソールに直接描画され、通常の入出力ストリームを一切経由しません。stdout に出力される唯一のものは、Enter を押したときに出力される最終的な選択パス (1 行につき 1 件) だけです。これにより、他のコマンドの結果を取得するための通常のシェルのテクニックと組み合わせて使うことができます。</p><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; code $path</span></span></code></pre></div><p>cmd.exe (組み込みのコマンド置換がないため <code>for /f</code> を使用):</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="制限事項" tabindex="-1">制限事項 <a class="header-anchor" href="#制限事項" aria-label="Permalink to &quot;制限事項&quot;">​</a></h2><ul><li>プレビューパネルはありません — App 自身の<a href="./actions-and-preview.html">アクションメニューとプレビュー</a>がすでにその役割を担っているため、意図的に対象外としています。</li><li>Lertaro App が実行されている必要があります。<code>lff</code> 自体は何もインデックス化しません。</li></ul>`,25)])])}const u=t(d,[["render",l]]);export{f as __pageData,u as default};
